window.RKI_SEARCH_INDEX = [{"title": "Разработка компьютерных игр", "pageTitle": "Разработка компьютерных игр", "url": "index.html", "body": "Задание второго этапа сезона 2026–2027. Всё о проекте, четырех блоках работы и сдаче материалов — в одном месте."}, {"title": "Общая информация", "pageTitle": "Общая информация", "url": "general/index.html", "body": "Одна комната или одна сцена"}, {"title": "Общая задача", "pageTitle": "Общая информация", "url": "general/index.html#task", "body": "Разработайте камерную игру о реальной или вымышленной деятельности в одной комнате или на одной ограниченной сцене. Это может быть мастерская, лаборатория, диспетчерская, кухня или другая система. Сеттинг и стиль выберите самостоятельно; допустимы сочетания симуляции, менеджмента, головоломки, стратегии и нарративной игры. Возрастной рейтинг — 12+ Игра и все сданные материалы должны соответствовать возрастному рейтингу 12+. Подробные ограничения 12+ Результат — завершенная демоверсия для Windows на 10+ минут первого самостоятельного прохождения с обучением, без учета загрузок и технических пауз. Игрок должен освоить деятельность, столкнуться с изменением условий и получить понятный итог. Демоверсия станет основой работы на заключительном этапе. Основные действия происходят в одном воспринимаемом пространстве. Допустимы смена ракурса, приближение, окна приборов и изменение обстановки, но не переходы между самостоятельными игровыми локациями. Число технических сцен движка не ограничено. Свяжите не менее двух операций: результат одной должен влиять на другую. Дайте игроку выбор с различимыми последствиями. Например: распределение ресурсов, настройку параметров, подбор инструментов или порядок действий. Хотя бы один раз измените условия так, чтобы потребовалось пересмотреть решение: введите новый заказ, ограничение, неисправность или событие. Прогресс должен зависеть от решений и взаимодействия механик. Быстрый повтор одинакового действия сам по себе не должен давать преимущество. Ограничение времени допустимо для планирования; улучшения, если они есть, должны менять возможности игрока. Вся игра, включая обучение, меню, завершение и перезапуск, должна проходиться мышью. Клавиатура может использоваться только как дополнительный способ управления. Использование специального игрового оборудования запрещено (геймпады, контроллеры, Steam Deck и другие портативные игровые консоли, VR-оборудование и аналогичные устройства). Через интерфейс и игровые объекты объясните цель, действия, состояние системы и последствия решений. Игрок должен понимать причины ошибок и иметь возможность продолжить или начать заново. Заявленные ключевые механики должны работать в демоверсии. Документы, изображения и ролики должны соответствовать игре."}, {"title": "Команда и блоки", "pageTitle": "Общая информация", "url": "general/index.html#team", "body": "Рекомендуемый состав: 3–4 участника. Распределите роли геймдизайнера, программиста, художника и тимлида; роли можно совмещать. Тимлид объединяет материалы и организует сдачу, за содержание отвечает команда. Командообразование и участие в одиночку регулируются Правилами II этапа. Геймдизайн 100 баллов Арт 100 баллов Программирование 100 баллов Продукт 150 баллов"}, {"title": "Сроки", "pageTitle": "Общая информация", "url": "general/index.html#dates", "body": "Открытие всех блоков 10 ноября 2026 Сдача геймдизайна 21 ноября 2026 Сдача арта и программирования 28 ноября 2026 Сдача продукта и окончание этапа 1 декабря 2026 Апелляция 12 декабря 2026 Публикация итогов 21 декабря 2026"}, {"title": "Инструменты и самостоятельность", "pageTitle": "Общая информация", "url": "general/index.html#tools", "body": "Используйте Unreal Engine, Godot или Unity и укажите версию движка. Сдавайте сборки для Windows. Применение другого движка влечет аннулирование результатов команды по задаче инженерного тура в соответствии с Правилами II этапа. Создавайте решение в период этапа. Запрещены заранее подготовленные командой проекты и компоненты, платные ассеты и использование программного обеспечения, требующего приобретения платной лицензии. Не выдавайте чужую работу за свою и не передавайте решения другим командам. В художественных материалах разрешены генеративные модели: проверьте и доработайте результат под проект, укажите модель и область использования в списке источников. Команда отвечает за результат и должна уметь объяснить свои решения."}, {"title": "Вопросы организаторам", "pageTitle": "Общая информация", "url": "general/index.html#questions", "body": "По всем вопросам обращайтесь в Telegram-группу участников. Задавайте вопросы организаторам в соответствующих темах. Telegram-группа участников"}, {"title": "Возрастной рейтинг 12+", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html", "body": "Создавайте игру, подходящую для игроков от 12 лет. Соблюдайте эти ограничения в игре и во всех материалах сдачи."}, {"title": "К чему относятся ограничения", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#scope", "body": "Проверяйте сюжет, действия игрока, изображения, анимации, интерфейс, диалоги, озвучку, музыку и звуки. Те же требования действуют для артбука, документов, презентации, тизера и других роликов, включая референсы и сторонние материалы. Надпись «12+», предупреждение или необязательность сцены не делают неподходящее содержание допустимым. Скрытые сцены, альтернативные концовки и бонусные материалы тоже должны соответствовать ограничениям."}, {"title": "Насилие и жестокость", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#violence", "body": "Допустимы отдельные, оправданные сюжетом эпизоды без подробного показа ранений, увечий и гибели. Не смакуйте боль и страдания, не делайте жестокость развлечением. Покажите сочувствие пострадавшим и осуждение жестокости. Сексуальное насилие недопустимо."}, {"title": "Страх, болезни и смерть", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#fear", "body": "Приключенческое напряжение и условная опасность допустимы. Болезни показывайте кратко, без подробностей и унижения человека. Аварии, катастрофы и смерть не должны сопровождаться шокирующими последствиями, способными вызвать сильный страх, ужас или панику. Исключите реалистичные мучения, обезображенные тела и подробности тяжелых заболеваний."}, {"title": "Речь и юмор", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#language", "body": "Не используйте мат и бранные выражения — в том числе в песнях, озвучке, надписях и названиях. Замена букв символами или частичное заглушение не подходят, если выражение остается узнаваемым. Юмор не должен строиться на сексуальных подробностях, унижении или жестокости."}, {"title": "Романтика и сексуальное содержание", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#romance", "body": "Допустимы симпатия, влюбленность и ненавязчивая романтика без откровенных подробностей. Не включайте сексуальные действия, эротические сцены, сексуализированную наготу и возбуждающие описания. Изображения, ракурсы и анимации не должны акцентировать сексуальные детали."}, {"title": "Алкоголь, никотин и наркотики", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#substances", "body": "Не поощряйте употребление и не связывайте его с успехом, привлекательностью или преимуществами. Наркотики, табак, вейпы и другие устройства для употребления никотина допустимо лишь кратко упоминать, без показа. Такие упоминания, как и сцены с алкоголем, должны ясно осуждать употребление и обозначать его вред. Исключите инструкции по изготовлению, приобретению и употреблению."}, {"title": "Азартные игры и противоправное поведение", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#gambling", "body": "Не призывайте к ставкам, азартным играм или преступлениям и не представляйте их как привлекательный способ заработать. Сюжетные упоминания и отдельные эпизоды допустимы без инструкций и оправдания такого поведения, с понятным отрицательным отношением. Случайный результат обычной игровой механики сам по себе не означает азартную игру."}, {"title": "Опасное поведение и отношение к людям", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#danger", "body": "Не включайте призывы, инструкции или поощрение самоубийства, самоповреждения и опасных действий, которые можно повторить в жизни. Не оправдывайте травлю, унижение людей и жестокость к животным. Конфликт может быть частью сюжета, но не должен превращаться в одобрение причинения вреда."}, {"title": "Перед сдачей", "pageTitle": "Возрастной рейтинг 12+", "url": "age-rating/index.html#check", "body": "Просмотрите весь проект, включая необязательные ветки, фоновые изображения и звуковые дорожки. Оценивайте не только сам эпизод, но и его подробность, длительность, повторяемость и роль в игре. Мультяшный стиль и вымышленный мир не отменяют ограничений. Если сомневаетесь в конкретной сцене или механике, заранее задайте вопрос организаторам в соответствующей теме Telegram-группы. Задать вопрос организаторам"}, {"title": "Геймдизайн", "pageTitle": "Геймдизайн", "url": "game-design/index.html", "body": "Свяжите желаемый опыт игрока с действиями, игровыми циклами и механиками."}, {"title": "Концепция и механики", "pageTitle": "Геймдизайн", "url": "game-design/index.html#document", "body": "Подготовьте концепт-документ / дизайн-документ по предоставленному шаблону. Свяжите аудиторию и желаемый опыт с действиями игрока, игровыми циклами и механиками. Ключевые механики должны быть реализованы в демоверсии. Шаблон для заполнения"}, {"title": "Что сдать", "pageTitle": "Геймдизайн", "url": "game-design/index.html#files", "body": "НазваниеПроекта_ТалантIDКоманды_Геймдизайн.pdf Концепт-документ / дизайн-документ в папке 01_Геймдизайн. Имя файла должно начинаться с префикса НазваниеПроекта_ТалантIDКоманды_."}, {"title": "Арт", "pageTitle": "Арт", "url": "art/index.html", "body": "Соберите визуальный образ игры в артбуке из семи страниц."}, {"title": "Формат артбука", "pageTitle": "Арт", "url": "art/index.html#format", "body": "Подготовьте артбук: ровно 7 горизонтальных страниц A4 (297 × 210 мм) в PDF. Пронумеруйте страницы с обложки, используя одинаковые расположение, шрифт и размер номеров. Согласуйте палитру, графику и типографику с игрой. Выстройте композицию, масштаб изображений и поля; оставьте только названия и краткие пояснения. Допустимы скриншоты, рендеры, иллюстрации и концепт-арты. Концепты подпишите и свяжите с реализованными решениями. Выбор 2D или 3D и сложность техники остаются за командой."}, {"title": "01 · Обложка", "pageTitle": "Арт", "url": "art/index.html#cover", "body": "Разместите кей-арт на всю страницу, название игры и команды. Главный объект или действие должны передавать деятельность и атмосферу проекта; название должно легко читаться."}, {"title": "02 · Нарратив", "pageTitle": "Арт", "url": "art/index.html#narrative", "body": "Раскройте мир, атмосферу и сюжетную ситуацию не менее чем в двух содержательно разных изображениях через среду, события или состояния."}, {"title": "03 · Сцена", "pageTitle": "Арт", "url": "art/index.html#scene", "body": "Покажите общий вид и не менее двух дополнительных ракурсов, зон или состояний той же сцены. Обозначьте рабочие зоны и их связи, отличите интерактивные объекты от декора. Используйте свет и цвет для направления внимания."}, {"title": "04 · Объекты", "pageTitle": "Арт", "url": "art/index.html#objects", "body": "Представьте не менее четырех разных объектов, включая игровые и декоративные. Форма и детали должны помогать понять назначение."}, {"title": "05 · Персонажи или функциональные аналоги", "pageTitle": "Арт", "url": "art/index.html#characters", "body": "Покажите всех главных героев и не менее двух персонажей или аналогов. Если в игре только один, представьте не менее двух значимых состояний и поясните это в подписи. Аналогами могут быть устройства, существа или интерфейсные помощники, выполняющие функции персонажей. Передайте роль и характер через силуэт, форму, цвет и детали, сохраняя пропорции и стиль игры."}, {"title": "06 · Механики и анимации", "pageTitle": "Арт", "url": "art/index.html#animation", "body": "Покажите хотя бы одну последовательность из трех и более кадров: исходное состояние, действие и результат. Она должна объяснять работающую механику."}, {"title": "07 · Интерфейс", "pageTitle": "Арт", "url": "art/index.html#interface", "body": "Покажите основной игровой экран и не менее трех типов элементов UI. Для интерактивного элемента представьте доступное состояние и недоступное либо выбранное. Назначение, текст и различия состояний должны читаться."}, {"title": "Что сдать", "pageTitle": "Арт", "url": "art/index.html#files", "body": "Источники сторонних изображений вынесите в отдельный файл, сохранив объем артбука в 7 страниц. Артбук.pdf Ровно 7 страниц. Источники.pdf Источники сторонних изображений. Разместите файлы в папке 02_Арт. К каждому имени файла добавьте префикс НазваниеПроекта_ТалантIDКоманды_."}, {"title": "Программирование", "pageTitle": "Программирование", "url": "programming/index.html", "body": "Реализуйте центральный игровой цикл и объясните его устройство в презентации."}, {"title": "Выбор уровня", "pageTitle": "Программирование", "url": "programming/index.html#levels", "body": "Выберите один из трех уровней. Уровни накопительные: для среднего нужно полностью выполнить задание начального, для высшего — начального и среднего. Максимумы указаны с учетом предыдущих уровней. Шаблон для заполнения"}, {"title": "Начальный уровень · до 30 баллов", "pageTitle": "Программирование", "url": "programming/index.html#basic", "body": "Реализуйте полный центральный цикл от действия игрока до результата. Допустимы жесткие связи модулей и создание объектов во время выполнения. Представьте архитектурный граф, блок-схему алгоритма и схему данных: объясните назначение модулей, входы, результаты, обмен данными и ветвления."}, {"title": "Средний уровень · до 70 баллов", "pageTitle": "Программирование", "url": "programming/index.html#intermediate", "body": "Дополните начальный уровень декомпозицией и отделением данных от логики. Обозначьте ответственность, входы и выходы модулей. Покажите типовой сценарий их взаимодействия и места настройки. Вынесите параметры в конфигурации или внутренние форматы данных, приведите структуру и заполненный пример. Проверьте контролируемую реакцию на ошибочный или граничный набор данных без разрушения состояния."}, {"title": "Высший уровень · до 100 баллов", "pageTitle": "Программирование", "url": "programming/index.html#advanced", "body": "Дополните предыдущие уровни независимостью модулей и расширением через данные. Добавьте элемент существующего типа через данные без изменения исходного кода. Приложите инструкцию, исходный и измененный варианты данных, покажите новый элемент в игре."}, {"title": "Видео центрального цикла", "pageTitle": "Программирование", "url": "programming/index.html#video", "body": "Запишите полный цикл в MP4: до 3 минут, не ниже 1280 × 720. Покажите интерфейс, действия, изменения состояния и результат; свяжите запись со схемами надписями или таймкодами. Дополнительные видео не входят в трехминутный ролик."}, {"title": "Git-репозиторий", "pageTitle": "Программирование", "url": "programming/index.html#repository", "body": "Приложите TXT-файл со ссылкой на Git-репозиторий. Репозиторий должен быть публичным либо доступным следующим аккаунтам организаторов: Numillyash https://github.com/Numillyash Numillyash-std@yandex.ru Professor0Ice https://github.com/Professor0Ice matt_bmw@mail.ru"}, {"title": "Что сдать", "pageTitle": "Программирование", "url": "programming/index.html#files", "body": "Архитектура.pdf Презентация об устройстве центрального игрового цикла. ОсновнойИгровойЦикл.mp4 До 3 минут, не ниже 1280 × 720. Репозиторий.txt Ссылка на Git-репозиторий. Дополнительные демонстрации Для среднего и высшего уровней. Разместите файлы в папке 03_Программирование. К каждому имени файла добавьте префикс НазваниеПроекта_ТалантIDКоманды_."}, {"title": "Продукт", "pageTitle": "Продукт", "url": "product/index.html", "body": "Сдайте завершенную демоверсию и материалы, представляющие игру игроку и потенциальному издателю."}, {"title": "Демоверсия", "pageTitle": "Продукт", "url": "product/index.html#demo", "body": "Сдайте в ZIP игру, собранную для Windows. Она должна запускаться и проходиться до конца без блокирующих ошибок и сбоев, мешающих управлению. Редактор движка и платные зависимости для запуска не должны требоваться. README необязателен. При необходимости добавьте в него пояснения к игре."}, {"title": "Тестирование", "pageTitle": "Продукт", "url": "product/index.html#playtest", "body": "Проведите тест минимум с одним человеком вне команды без устных пояснений разработчиков. Проверьте понимание цели, управления, состояния системы и последствий действий. Измерьте первое прохождение с обучением, исключив загрузки и технические паузы; не увеличивайте время искусственным ожиданием. Создайте протокол плейтеста в PDF и укажите в нем: обезличенное обозначение тестировщика и соответствие аудитории, дату, версию игры, устройство, условия, длительность, наблюдения, проблемы и решения команды. Повторно проверьте выводы и опишите результат. Если проблем нет, приведите проверенные ситуации и наблюдения. Контакты тестировщика не нужны."}, {"title": "Тизер", "pageTitle": "Продукт", "url": "product/index.html#teaser", "body": "Подготовьте видео MP4 длительностью до 30 секунд с заставками и финальной карточкой, 16:9, не ниже 1920 × 1080. Укажите название игры и команды. На кадрах демоверсии покажите пространство, деятельность, действие игрока и результат. Выстройте акцент и завершение, дайте рассмотреть происходящее. Текст, монтаж и звук должны поддерживать атмосферу; графика не должна создавать впечатление несуществующих механик."}, {"title": "Два вертикальных ролика", "pageTitle": "Продукт", "url": "product/index.html#vertical", "body": "Подготовьте два отдельных рекламных видео о вашей игре, MP4 по 15–30 секунд, 9:16, не ниже 1080 × 1920. Укажите название игры в каждом ролике, команду и номер в имени файла. Каждый ролик должен быть понятен отдельно и показывать ситуацию, ее развитие и результат. Раскройте разные особенности вашей игры или разные решения игрока и их последствия. Сохраните читаемость текста и значимого UI в окне 360 × 640 CSS-пикселей без увеличения, подберите монтаж и звук под ситуацию. Публикация в социальных сетях не требуется."}, {"title": "Презентация проекта", "pageTitle": "Продукт", "url": "product/index.html#pitch", "body": "Подготовьте PDF для потенциального издателя или инвестора по шаблону. Представьте игру, аудиторию, желаемый опыт, референсы, деятельность и цикл, механики, визуальный стиль, команду и роли. Покажите демоверсию, объясните отличия, модель распространения и потенциал развития. Подкрепите выводы примерами из игры и сравнением с референсами. Отделите готовое от планов и соотнесите развитие с демоверсией и возможностями команды. Число слайдов не ограничено; текст, скриншоты и схемы должны читаться на экране 1920 × 1080 без увеличения. Публичное выступление не требуется. Шаблон презентации проекта"}, {"title": "Что сдать", "pageTitle": "Продукт", "url": "product/index.html#files", "body": "Сборка_Продукт.zip Демоверсия для Windows. Тизер.mp4 До 30 секунд, 16:9, не ниже 1920 × 1080. ВертикальноеВидео_01.mp4 15–30 секунд, 9:16, не ниже 1080 × 1920. ВертикальноеВидео_02.mp4 15–30 секунд, 9:16, не ниже 1080 × 1920. Питч.pdf Презентация для потенциального издателя или инвестора. Плейтест.pdf Протокол тестирования. Разместите файлы в папке 04_Продукт. К каждому имени файла добавьте префикс НазваниеПроекта_ТалантIDКоманды_."}, {"title": "Порядок сдачи", "pageTitle": "Порядок сдачи", "url": "submission/index.html", "body": "Соберите материалы на Google Диске и отправьте ссылку на папку блока через форму «Талант»."}, {"title": "Структура материалов", "pageTitle": "Порядок сдачи", "url": "submission/index.html#structure", "body": "Разместите материалы на Google Диске в папке Project_RKI_2026_27 с четырьмя папками блоков. Вместо Project используйте короткое название проекта латиницей без пробелов. Другие хранилища и видеохостинги не заменяют сдачу. Исходный проект передается через Git-репозиторий по ссылке в TXT-файле блока «Программирование». К именам файлов в таблице добавляйте единый префикс НазваниеПроекта_ТалантIDКоманды_. 01_Геймдизайн Геймдизайн.pdf 02_Арт Артбук.pdf\nИсточники.pdf 03_Программирование Архитектура.pdf\nОсновнойИгровойЦикл.mp4\nРепозиторий.txt\nДля среднего и высшего уровней — дополнительные демонстрации 04_Продукт Сборка_Продукт.zip\nТизер.mp4\nВертикальноеВидео_01.mp4\nВертикальноеВидео_02.mp4\nПитч.pdf\nПлейтест.pdf Пример папки проекта Panakota_RKI_2026_27 Панакота 123456 Условный пример. Все файлы сданы в срок, доступ на просмотр и скачивание открыт. 01_Геймдизайн 21.11.2026  Панакота_123456_Геймдизайн.pdf 02_Арт 28.11.2026  Панакота_123456_Артбук.pdf Панакота_123456_Источники.pdf 03_Программирование 28.11.2026 Дополнительные демонстрации — для среднего и высшего уровней. Панакота_123456_Архитектура.pdf Панакота_123456_ОсновнойИгровойЦикл.mp4 Панакота_123456_Репозиторий.txt Панакота_123456_ДополнительнаяДемонстрация_01.mp4 04_Продукт 01.12.2026  Панакота_123456_Сборка_Продукт.zip Панакота_123456_Тизер.mp4 Панакота_123456_ВертикальноеВидео_01.mp4 Панакота_123456_ВертикальноеВидео_02.mp4 Панакота_123456_Питч.pdf Панакота_123456_Плейтест.pdf Источники сторонних материалов указывайте в документах или отдельных списках. Разделите код, ассеты и документацию по понятным каталогам. Исключите ненужные временные файлы и кэши. Не используйте пароли, шифрование и исполняемые самораспаковывающиеся архивы. К каждому сроку сдавайте отдельный комплект, соответствующий версии игры своего блока. Разработку можно продолжать, сохраняя сданные файлы без изменений. Продуктовые ролики и презентация должны соответствовать итоговой демоверсии."}, {"title": "Доступ к материалам", "pageTitle": "Порядок сдачи", "url": "submission/index.html#access", "body": "На Google Диске включите доступ «Все, у кого есть ссылка» с просмотром и скачиванием. Проверьте папки, вложенные файлы и ссылки из презентаций в приватном окне без входа в Google. К закрытому репозиторию предоставьте доступ указанным аккаунтам организаторов. Проверьте запуск скачанных сборок, открытие PDF и воспроизведение видео. Numillyash https://github.com/Numillyash Numillyash-std@yandex.ru Professor0Ice https://github.com/Professor0Ice matt_bmw@mail.ru"}, {"title": "Отправка и сохранность", "pageTitle": "Порядок сдачи", "url": "submission/index.html#send", "body": "До соответствующего срока представитель команды отправляет ссылку на папку блока через форму «Талант». Размещение файлов без отправки формы не является сдачей. Сохраняйте доступ к материалам и репозиторию до завершения проверки и апелляций. После срока не изменяйте и не заменяйте сданные файлы на Google Диске."}];
